sc_cat_item_producer.script:
(function() {

    producer.portal_redirect = "?id=hoc_ohsm_confirmation&requestNumber=" + current.number + "&anonymous=true";

    var aislesHazards = JSON.parse(producer.hazard_s_to_report_in_aisles_and_flooring);
	var environmentHazards = JSON.parse(producer.hazard_s_to_report_in_environment);
	var electricalHazards = JSON.parse(producer.hazard_s_to_report_in_electrical);
	var firstAidHazards = JSON.parse(producer.hazard_s_to_report_in_first_aid_and_emergency_preparedness);
	var housekeepingHazards = JSON.parse(producer.hazard_s_to_housekeeping);
	var postingHazards = JSON.parse(producer.hazard_s_to_posting_requirements);
	var storageHazards = JSON.parse(producer.hazard_s_to_storage_shelving_and_cabinets);
	var washroomsHazards = JSON.parse(producer.hazard_s_to_washrooms_and_kitchens);
	var outdoorHazards = JSON.parse(producer.hazard_s_to_outdoor);
	var otherHazards = JSON.parse(producer.hazard_s_to_others);

	//If has an existing draft exist, delete the draft before another report gets created
	if (producer.case_sys_id != ""){
		var rec = new GlideRecord("x_hccc_hoc_ohs_investigation_case");
		rec.addQuery('sys_id',producer.case_sys_id);
		rec.query();		
		if (rec.next()){
			current.number = rec.number;
			rec.deleteRecord();
		}
	}

	//If save as a draft, save as a draft
	if (producer.report_submission == "Save as a draft"){
		var producer_copy = createCurrentCopy();
		current.wi_building = producer.building;
		current.wi_floor_inspected = producer.floor_inspected.getDisplayValue();
		current.wi_area_inspected = producer.area_s_inspected;
		current.wi_area_s_not_inspected = producer.area_s_not_inspected;
		current.wi_date_time_of_inspection = producer.date_time_of_inspection;
		current.wi_shared_space = producer.shared_space;
		current.hr_service = 'a94b0c891b7e7c109fde86acdd4bcbc1';
		current.short_description = 'Incident report on ' + producer.building.getDisplayValue() + " (floor " + producer.floor_inspected.getDisplayValue() + ") at " + producer.date_time_of_inspection.getDisplayValue();
		current.subject_person = producer.inspector_name;
		current.opened_for = producer.inspector_name;
		current.state = 903; //Draft
		current.json_draft = JSON.stringify(producer_copy);
		return;
	}

	//----------------------------------------------------------------------------
	//Create parent case (Current) -----------------------------------------------
	//----------------------------------------------------------------------------
	current.hr_service = 'a94b0c891b7e7c109fde86acdd4bcbc1';
	current.short_description = generateReportShortDescription();
	current.subject_person = producer.inspector_name;
	current.opened_for = producer.inspector_name;
	current.rich_description = generateDescription();

	current.wi_building = producer.building;
	current.wi_floor_inspected = producer.floor_inspected.getDisplayValue();
	current.wi_area_inspected = producer.area_s_inspected;
	current.wi_area_s_not_inspected = producer.area_s_not_inspected;
	current.wi_date_time_of_inspection = producer.date_time_of_inspection;
	current.wi_shared_space = producer.shared_space;

	//Create inspector(s) in x_hccc_hoc_ohs_other_inspectors (parent_case, inspector)
	var grInspectors = new GlideRecord("x_hccc_hoc_ohs_other_inspectors");	
	grInspectors.initialize();
	grInspectors.parent_case = current.sys_id;
	grInspectors.inspector = producer.inspector_name;
	grInspectors.insert();	

	var inspectors = '' + producer.other_inspectors;
	if (inspectors != "") {
		var inspectors_array = inspectors.split(',');
		for (var i = 0; i < inspectors_array.length; i++) {
			grInspectors.initialize();
			grInspectors.parent_case = current.sys_id;
			grInspectors.inspector = inspectors_array[i];
			grInspectors.insert();				
		}
	}

	//2) CREATE CHILD CASES
	var hasOpenCorrectiveMeasure = false;

	var hazard = [];
	var room = [];
	var location = [];
	var hazard_removed = [];
	var hazard_category = [];
	var consequence = [];
	var likelihood = [];
	var comments = [];
	var manager = [];
	var recommendation = []; 

	//APPREND Corrective action for AISLES AND FLOORING
	var corrective_action_count = aislesHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(aislesHazards[i].aisles__hazard);
		room.push(aislesHazards[i].aisles__room);
		location.push(aislesHazards[i].aisles__location);
		hazard_removed.push(aislesHazards[i].aisles__hazard_removed);
		hazard_category.push(aislesHazards[i].aisles__hazard_category);
		consequence.push(aislesHazards[i].aisles__consequence);
		likelihood.push(aislesHazards[i].aisles__likelihood);
		comments.push(aislesHazards[i].aisles__comments);
		manager.push(aislesHazards[i].aisles__manager_responsible_for_the_area);
		recommendation.push(aislesHazards[i].aisles__recommendations);
	}

	//APPREND Corrective action for ENVIRONMENT
	corrective_action_count = environmentHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(environmentHazards[i].environment__hazard);
		room.push(environmentHazards[i].environment__room);
		location.push(environmentHazards[i].environment__location);
		hazard_removed.push(environmentHazards[i].environment__hazard_removed);
		hazard_category.push(environmentHazards[i].environment__hazard_category);
		consequence.push(environmentHazards[i].environment__consequence);
		likelihood.push(environmentHazards[i].environment__likelihood);
		comments.push(environmentHazards[i].environment__comments);
		manager.push(environmentHazards[i].environment__manager_responsible_for_the_area);
		recommendation.push(environmentHazards[i].environment__recommendations);
	}

	//APPREND Corrective action for ELECTRICAL
	corrective_action_count = electricalHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(electricalHazards[i].electrical__hazard);
		room.push(electricalHazards[i].electrical__room);
		location.push(electricalHazards[i].electrical__location);
		hazard_removed.push(electricalHazards[i].electrical__hazard_removed);
		hazard_category.push(electricalHazards[i].electrical__hazard_category);
		consequence.push(electricalHazards[i].electrical__consequence);
		likelihood.push(electricalHazards[i].electrical__likelihood);
		comments.push(electricalHazards[i].electrical__comments);
		manager.push(electricalHazards[i].electrical__manager_responsible_for_the_area);
		recommendation.push(electricalHazards[i].electrical__recommendations);
	}

	//APPREND Corrective action for FIRST AID
	corrective_action_count = firstAidHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(firstAidHazards[i].first_aid__hazard);
		room.push(firstAidHazards[i].first_aid__room);
		location.push(firstAidHazards[i].first_aid__location);
		hazard_removed.push(firstAidHazards[i].first_aid__hazard_removed);
		hazard_category.push(firstAidHazards[i].first_aid__hazard_category);
		consequence.push(firstAidHazards[i].first_aid__consequence);
		likelihood.push(firstAidHazards[i].first_aid__likelihood);
		comments.push(firstAidHazards[i].first_aid__comments);
		manager.push(firstAidHazards[i].first_aid__manager_responsible_for_the_area);
		recommendation.push(firstAidHazards[i].first_aid__recommendations);
	}


	//APPREND Corrective action for HOUSEKEEPING
	corrective_action_count = housekeepingHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(housekeepingHazards[i].housekeeping__hazard);
		room.push(housekeepingHazards[i].housekeeping__room);
		location.push(housekeepingHazards[i].housekeeping__location);
		hazard_removed.push(housekeepingHazards[i].housekeeping__hazard_removed);
		hazard_category.push(housekeepingHazards[i].housekeeping__hazard_category);
		consequence.push(housekeepingHazards[i].housekeeping__consequence);
		likelihood.push(housekeepingHazards[i].housekeeping__likelihood);
		comments.push(housekeepingHazards[i].housekeeping__comments);
		manager.push(housekeepingHazards[i].housekeeping__manager_responsible_for_the_area);
		recommendation.push(housekeepingHazards[i].housekeeping__recommendations);
	}

	//APPREND Corrective action for POSTING
	corrective_action_count = postingHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(postingHazards[i].posting__hazard);
		room.push(postingHazards[i].posting__room);
		location.push(postingHazards[i].posting__location);
		hazard_removed.push(postingHazards[i].posting__hazard_removed);
		hazard_category.push(postingHazards[i].posting__hazard_category);
		consequence.push(postingHazards[i].posting__consequence);
		likelihood.push(postingHazards[i].posting__likelihood);
		comments.push(postingHazards[i].posting__comments);
		manager.push(postingHazards[i].posting__manager_responsible_for_the_area);
		recommendation.push(postingHazards[i].posting__recommendations);
	}

	//APPREND Corrective action for STORAGE
	corrective_action_count = storageHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(storageHazards[i].storage__hazard);
		room.push(storageHazards[i].storage__room);
		location.push(storageHazards[i].storage__location);
		hazard_removed.push(storageHazards[i].storage__hazard_removed);
		hazard_category.push(storageHazards[i].storage__hazard_category);
		consequence.push(storageHazards[i].storage__consequence);
		likelihood.push(storageHazards[i].storage__likelihood);
		comments.push(storageHazards[i].storage__comments);
		manager.push(storageHazards[i].storage__manager_responsible_for_the_area);
		recommendation.push(storageHazards[i].storage__recommendations);
	}

	//APPREND Corrective action for WASHROOMS
	corrective_action_count = washroomsHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(washroomsHazards[i].washrooms__hazard);
		room.push(washroomsHazards[i].washrooms__room);
		location.push(washroomsHazards[i].washrooms__location);
		hazard_removed.push(washroomsHazards[i].washrooms__hazard_removed);
		hazard_category.push(washroomsHazards[i].washrooms__hazard_category);
		consequence.push(washroomsHazards[i].washrooms__consequence);
		likelihood.push(washroomsHazards[i].washrooms__likelihood);
		comments.push(washroomsHazards[i].washrooms__comments);
		manager.push(washroomsHazards[i].washrooms__manager_responsible_for_the_area);
		recommendation.push(washroomsHazards[i].washrooms__recommendations);
	}


	//APPREND Corrective action for OUTDOOR
	corrective_action_count = outdoorHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(outdoorHazards[i].outdoor__hazard);
		room.push(outdoorHazards[i].outdoor__room);
		location.push(outdoorHazards[i].outdoor__location);
		hazard_removed.push(outdoorHazards[i].outdoor__hazard_removed);
		hazard_category.push(outdoorHazards[i].outdoor__hazard_category);
		consequence.push(outdoorHazards[i].outdoor__consequence);
		likelihood.push(outdoorHazards[i].outdoor__likelihood);
		comments.push(outdoorHazards[i].outdoor__comments);
		manager.push(outdoorHazards[i].outdoor__manager_responsible_for_the_area);
		recommendation.push(outdoorHazards[i].outdoor__recommendations);
	}

	//APPREND Corrective action for OTHERS
	corrective_action_count = otherHazards.length;
	for (var i = 0; i < corrective_action_count; i++) {
		hazard.push(otherHazards[i].others__hazard);
		room.push(otherHazards[i].others__room);
		location.push(otherHazards[i].others__location);
		hazard_removed.push(otherHazards[i].others__hazard_removed);
		hazard_category.push(otherHazards[i].others__hazard_category);
		consequence.push(otherHazards[i].others__consequence);
		likelihood.push(otherHazards[i].others__likelihood);
		comments.push(otherHazards[i].others__comments);
		manager.push(otherHazards[i].others__manager_responsible_for_the_area);
		recommendation.push(otherHazards[i].others__recommendations);
	}

	//Create correction actions records
	if (hazard.length > 0){
		var grCA = new GlideRecord("x_hccc_hoc_ohs_investigation_case");
		hasOpenCorrectiveMeasure = true;
		var matrix = [[1,1,2,2,2],[1,2,2,2,2],[1,2,2,2,2],[1,2,2,2,3],[1,2,3,3,3]];

		for (var x=0;x<hazard.length;x++){
			grCA.initialize();
			grCA.hr_service = 'a284e0261b7a30109fde86acdd4bcbfc';
			grCA.opened_for = manager[x];
			grCA.wi_room = room[x];
			grCA.short_description = generateCorrectiveActionShortDescription(hazard[x]);
			grCA.wi_floor_inspected = producer.floor_inspected.getDisplayValue();
			grCA.wi_area_inspected = producer.area_inspected;
			grCA.wi_area_s_not_inspected = producer.area_s_not_inspected;
			grCA.wi_shared_space = producer.shared_space;
			grCA.inspectors = producer.inspector_name;//inspectors;
			grCA.parent = current.sys_id;
			hazard_removed[x] == "no" ? grCA.state = 900 : grCA.state = 902; //(900=Open, 902=Completed)
			grCA.hazard_removed = hazard_removed[x];
			grCA.wi_location = location[x];
			grCA.wi_building = producer.building;
			grCA.wi_hazard = hazard[x];
			grCA.wi_hazard_category = hazard_category[x];
			grCA.wi_comments = comments[x];
			grCA.wi_manager_responsible_for_the_area = manager[x];
			grCA.u_wi_recommendation = recommendation[x];

			if (hazard_removed[x] == "no"){
				grCA.wi_hazard_rating = matrix[consequence[x]-1][likelihood[x]-1];
			}
			grCA.insert();
		}

	}

	//Define state as "Open" (900) if at least one corrective action has been created, and "Completed" (902) otherwise
	hasOpenCorrectiveMeasure ? current.state = 900 : current.state = 902;

})();


function generateDescription(){
	var description = "";
	description+=producer.floors_are_clear;
	description+=producer.signs_are_posted_when_the_floors_are_wet;
	description+=producer.walkways_are_free_from_obstructions;
	description+=producer.main_aisles_are_at_least_36_inches_wide;
	description+=producer.lighting_levels_are_operational_entrance_office_and_stairways;
	description+=producer.air_quality_is_adequate;
	description+=producer.temperature_is_adequate;
	description+=producer.noise_levels_are_appropriate;




	 /*
	producer_copy.ventilation_is_adequate = '' + producer.ventilation_is_adequate;
	producer_copy.hazardous_products_are_properly_identified = '' + producer.hazardous_products_are_properly_identified;
	producer_copy.ceiling_tiles_are_in_good_condition = '' + producer.ceiling_tiles_are_in_good_condition;
