	producer_copy.security_systems_intercom_duress_alarm_etc = '' + producer.security_systems_intercom_duress_alarm_etc;
	producer_copy.is_the_office_furniture_ergonomic_and_in_good_condition = '' + producer.is_the_office_furniture_ergonomic_and_in_good_condition;
	producer_copy.paper_trimmer_cutter_blade_is_closed_and_secured = '' + producer.paper_trimmer_cutter_blade_is_closed_and_secured;
	producer_copy.desk_and_file_cabinet_drawers_are_closed_while_not_in_use = '' + producer.desk_and_file_cabinet_drawers_are_closed_while_not_in_use;
	producer_copy.is_the_office_furniture_free_from_sharp_edges_and_corners = '' + producer.is_the_office_furniture_free_from_sharp_edges_and_corners;
