	producer_copy.see_the_posting_requirements_document_in_the_health_and_safety_representative_toolbox = '' + producer.see_the_posting_requirements_document_in_the_health_and_safety_representative_toolbox;
	producer_copy.materials_are_stored_securely_and_at_an_appropriate_height = '' + producer.materials_are_stored_securely_and_at_an_appropriate_height;
	producer_copy.material_and_storage_systems_are_secured_from_tipping_and_are_in_good_condition = '' + producer.material_and_storage_systems_are_secured_from_tipping_and_are_in_good_condition;
	producer_copy.step_stools_and_ladders_are_available_and_in_good_condition = '' + producer.step_stools_and_ladders_are_available_and_in_good_condition;
	producer_copy.storage_room_is_maintained_and_clean_if_applicable = '' + producer.storage_room_is_maintained_and_clean_if_applicable;
	producer_copy.washrooms_are_clean = '' + producer.washrooms_are_clean;
	producer_copy.hygiene_supplies_are_available_soap_towels_bathroom_tissue = '' + producer.hygiene_supplies_are_available_soap_towels_bathroom_tissue;
