//CREATES A COPY OF THE PRODUCER OBJECT THAT CAN BE SERIALIZED
function createCurrentCopy(){
	var producer_copy = {};

	var aislesHazards = JSON.parse(producer.hazard_s_to_report_in_aisles_and_flooring);
	var environmentHazards = JSON.parse(producer.hazard_s_to_report_in_environment);
	var electricalHazards = JSON.parse(producer.hazard_s_to_report_in_electrical);
	var firstAidHazards = JSON.parse(producer.hazard_s_to_report_in_first_aid_and_emergency_preparedness);
	var housekeepingHazards = JSON.parse(producer.hazard_s_to_housekeeping);
	var postingHazards = JSON.parse(producer.hazard_s_to_posting_requirements);
	var storageHazards = JSON.parse(producer.hazard_s_to_storage_shelving_and_cabinets);
	var washroomsHazards = JSON.parse(producer.hazard_s_to_washrooms_and_kitchens);
	var outdoorHazards = JSON.parse(producer.hazard_s_to_outdoor);
	var otherHazards = JSON.parse(producer.hazard_s_to_others);

	//Copy checkboxes
	producer_copy.floors_are_clear = '' + producer.floors_are_clear;
	producer_copy.signs_are_posted_when_the_floors_are_wet = '' + producer.signs_are_posted_when_the_floors_are_wet;
	producer_copy.walkways_are_free_from_obstructions = '' + producer.walkways_are_free_from_obstructions;
	producer_copy.main_aisles_are_at_least_36_inches_wide = '' + producer.main_aisles_are_at_least_36_inches_wide;
	producer_copy.lighting_levels_are_operational_entrance_office_and_stairways = '' + producer.lighting_levels_are_operational_entrance_office_and_stairways;
	producer_copy.air_quality_is_adequate = '' + producer.air_quality_is_adequate;
	producer_copy.temperature_is_adequate = '' + producer.temperature_is_adequate;
	producer_copy.noise_levels_are_appropriate = '' + producer.noise_levels_are_appropriate;
	producer_copy.ventilation_is_adequate = '' + producer.ventilation_is_adequate;
	producer_copy.hazardous_products_are_properly_identified = '' + producer.hazardous_products_are_properly_identified;
	producer_copy.ceiling_tiles_are_in_good_condition = '' + producer.ceiling_tiles_are_in_good_condition;
	producer_copy.cords_and_plugs_are_in_good_condition = '' + producer.cords_and_plugs_are_in_good_condition;
	producer_copy.power_bars_are_not_plugged_into_another_power_bar_daisy_chain = '' + producer.power_bars_are_not_plugged_into_another_power_bar_daisy_chain;
	producer_copy.space_heaters_are_csa_approved_and_have_an_auto_shut_off_feature = '' + producer.space_heaters_are_csa_approved_and_have_an_auto_shut_off_feature;
	producer_copy.wire_management_in_good_condition_and_are_not_a_tripping_hazard = '' + producer.wire_management_in_good_condition_and_are_not_a_tripping_hazard;
	producer_copy.first_aid_kits_are_inspected_on_a_monthly_basis_and_are_they_accessible = '' + producer.first_aid_kits_are_inspected_on_a_monthly_basis_and_are_they_accessible;
	producer_copy.fire_extinguishers_are_hung_properly_are_accessible_inspected_on_a_monthly_basis = '' + producer.fire_extinguishers_are_hung_properly_are_accessible_inspected_on_a_monthly_basis;
