function generateReportShortDescription(){
	return 'Incident report on ' + producer.building.getDisplayValue() + " (floor " + producer.floor_inspected.getDisplayValue() + ") at " + producer.date_time_of_inspection.getDisplayValue();
}

function generateCorrectiveActionShortDescription(hazard){
	return "Hazard: '" + hazard + "' at " + producer.building.getDisplayValue() + " (floor " + producer.floor_inspected.getDisplayValue() + ")";
}
